import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';

export function hashPassword(password) {
  const salt = randomBytes(16).toString('hex');
  const hash = scryptSync(password, salt, 64).toString('hex');
  return `${salt}:${hash}`;
}

export function verifyPassword(password, stored) {
  const [salt, hash] = stored.split(':');
  const expected = Buffer.from(hash, 'hex');
  const actual = scryptSync(password, salt, 64);
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}

import { createReadStream, createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';

export async function gzipFile(src, dest) {
  await pipeline(createReadStream(src), createGzip(), createWriteStream(dest));
}

export function memoizeAsync(fn, ttlMs) {
  const cache = new Map();
  return async (arg) => {
    const hit = cache.get(arg);
    if (hit && hit.expires > Date.now()) {
      return hit.value;
    }
    const value = await fn(arg);
    cache.set(arg, { value, expires: Date.now() + ttlMs });
    return value;
  };
}
